import React from 'react';
import PropTypes from 'prop-types';
import { GatsbyImage, getImage } from 'gatsby-plugin-image';
import styled, { css } from 'styled-components';
import { Icon } from '@components/icons';

const StyledProjectsGrid = styled.ul`
  ${({ theme }) => theme.mixins.resetList};

  a {
    position: relative;
    z-index: 1;
  }
`;

const StyledProject = styled.li`
  position: relative;
  display: grid;
  grid-gap: 10px;
  grid-template-columns: repeat(12, 1fr);
  align-items: center;

  @media (max-width: 768px) {
    ${({ theme }) => theme.mixins.boxShadow};
  }

  &:not(:last-of-type) {
    margin-bottom: 100px;

    @media (max-width: 768px) {
      margin-bottom: 70px;
    }

    @media (max-width: 480px) {
      margin-bottom: 30px;
    }
  }

  &:nth-of-type(odd) {
    .project-content {
      grid-column: 6 / -1;
      text-align: left;

      @media (max-width: 1080px) {
        grid-column: 4 / -1;
      }
      @media (max-width: 768px) {
        grid-column: 1 / -1;
        padding: 40px 40px 30px;
        text-align: left;
      }
      @media (max-width: 480px) {
        padding: 25px 25px 20px;
      }
    }
    .project-tech-list {
      justify-content: flex-end;

      @media (max-width: 768px) {
        justify-content: flex-start;
      }

      li {
        margin: 0 0 5px 20px;

        @media (max-width: 768px) {
          margin: 0 10px 5px 0;
        }
      }
    }
    .project-links {
      justify-content: flex-end;
      margin-left: 0;
      margin-right: -10px;

      @media (max-width: 768px) {
        justify-content: flex-start;
        margin-left: -10px;
        margin-right: 0;
      }
    }
    .project-image {
      grid-column: 1 / 6;

      @media (max-width: 768px) {
        grid-column: 1 / -1;
      }
    }
  }

  .project-content {
    position: relative;
    grid-column: 1 / 6;
    grid-row: 1 / -1;

    @media (max-width: 1080px) {
      grid-column: 1 / 10;
    }

    @media (max-width: 768px) {
      display: flex;
      flex-direction: column;
      justify-content: center;
      height: 100%;
      grid-column: 1 / -1;
      padding: 40px 40px 30px;
      z-index: 5;
    }

    @media (max-width: 480px) {
      padding: 30px 25px 20px;
    }
  }

  .project-overline {
    margin: 10px 0;
    color: var(--green);
    font-family: var(--font-mono);
    font-size: var(--fz-xs);
    font-weight: 400;
  }

  .project-title {
    color: var(--lightest-slate);
    font-size: clamp(24px, 5vw, 28px);

    @media (min-width: 768px) {
      margin: 0 0 20px;
    }

    @media (max-width: 768px) {
      color: var(--white);

      a {
        position: static;

        &:before {
          content: '';
          display: block;
          position: absolute;
          z-index: 0;
          width: 100%;
          height: 100%;
          top: 0;
          left: 0;
        }
      }
    }
  }

  .project-description {
    ${({ theme }) => theme.mixins.boxShadow};
    position: relative;
    z-index: 2;
    padding: 25px;
    border-radius: var(--border-radius);
    background-color: var(--light-navy);
    color: var(--light-slate);
    font-size: var(--fz-lg);

    @media (max-width: 768px) {
      padding: 20px 0;
      background-color: transparent;
      box-shadow: none;

      &:hover {
        box-shadow: none;
      }
    }

    a {
      ${({ theme }) => theme.mixins.inlineLink};
    }

    strong {
      color: var(--white);
      font-weight: normal;
    }
  }

  .project-tech-list {
    display: flex;
    flex-wrap: wrap;
    position: relative;
    z-index: 2;
    margin: 25px 0 10px;
    padding: 0;
    list-style: none;

    li {
      margin: 0 20px 5px 0;
      color: var(--light-slate);
      font-family: var(--font-mono);
      font-size: var(--fz-xs);
      white-space: nowrap;
    }

    @media (max-width: 768px) {
      margin: 10px 0;

      li {
        margin: 0 10px 5px 0;
        color: var(--lightest-slate);
      }
    }
  }

  .project-links {
    display: flex;
    align-items: center;
    position: relative;
    margin-top: 10px;
    margin-left: -10px;
    color: var(--lightest-slate);

    a {
      ${({ theme }) => theme.mixins.flexCenter};
      padding: 10px;

      &.external {
        svg {
          width: 22px;
          height: 22px;
          margin-top: -4px;
        }
      }

      svg {
        width: 20px;
        height: 20px;
      }
    }

    .cta {
      ${({ theme }) => theme.mixins.smallButton};
      margin: 10px;
    }
  }

  .project-image {
    ${({ theme }) => theme.mixins.boxShadow};
    grid-column: 6 / -1;
    grid-row: 1 / -1;
    position: relative;
    z-index: 1;

    @media (max-width: 768px) {
      grid-column: 1 / -1;
      height: 100%;
      opacity: 0.25;
    }

    a {
      width: 100%;
      height: 100%;
      background-color: var(--green);
      border-radius: var(--border-radius);
      vertical-align: middle;

      &:hover,
      &:focus {
        background: transparent;
        outline: 0;

        &:before,
        .img {
          background: transparent;
          filter: none;
        }
      }

      &:before {
        content: '';
        position: absolute;
        width: 100%;
        height: 100%;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        z-index: 3;
        transition: var(--transition);
        background-color: var(--navy);
        mix-blend-mode: screen;
      }
    }

    .img {
      border-radius: var(--border-radius);
      mix-blend-mode: multiply;
      filter: grayscale(100%) contrast(1) brightness(90%);

      @media (max-width: 768px) {
        object-fit: cover;
        width: auto;
        height: 100%;
        filter: grayscale(100%) contrast(1) brightness(50%);
      }
    }
  }

  ${props =>
    props.showcase &&
    css`
      .project-image {
        a {
          background-color: transparent;

          &:before {
            background-color: transparent;
            mix-blend-mode: normal;
          }
        }

        .img {
          mix-blend-mode: normal;
          filter: none;
          border: 1px solid var(--lightest-navy);
        }

        /* Screenshots come in whatever aspect ratio the app happens to be.
           Cap the height so a portrait one can't tower over the row and
           outweigh the projects above it; letterbox rather than crop. */
        img {
          max-height: 420px;
          object-fit: contain;
          object-position: center;
        }
      }

      /* On mobile the base styles overlap the image and the text in a single
         grid cell, fading the image to 25% as a backdrop. A UI screenshot has
         to stay legible, so stack them into two rows instead. */
      @media (max-width: 768px) {
        grid-template-columns: 1fr;
        box-shadow: none;

        &,
        &:nth-of-type(odd) {
          .project-image {
            grid-column: 1;
            grid-row: 1;
            height: auto;
            opacity: 1;
            margin-bottom: 25px;
          }

          .project-content {
            grid-column: 1;
            grid-row: 2;
            padding: 0;
          }
        }

        .project-image .img {
          object-fit: contain;
          width: 100%;
          height: auto;
          filter: none;
        }

        .project-image img {
          max-height: 340px;
        }

        .project-description {
          padding: 0;
        }
      }
    `};
`;

const FeaturedGrid = ({ projects, overline, showcase, revealRefs }) => (
  <StyledProjectsGrid>
    {projects &&
      projects.map(({ node }, i) => {
        const { frontmatter, html } = node;
        const { external, title, tech, github, cover, cta } = frontmatter;
        const image = getImage(cover);

        return (
          <StyledProject
            key={i}
            showcase={showcase}
            ref={el => {
              if (revealRefs) {
                revealRefs.current[i] = el;
              }
            }}>
            <div className="project-content">
              <div>
                <p className="project-overline">{overline}</p>

                <h3 className="project-title">
                  <a href={external}>{title}</a>
                </h3>

                <div className="project-description" dangerouslySetInnerHTML={{ __html: html }} />

                {tech.length && (
                  <ul className="project-tech-list">
                    {tech.map((tech, i) => (
                      <li key={i}>{tech}</li>
                    ))}
                  </ul>
                )}

                <div className="project-links">
                  {cta && (
                    <a href={cta} aria-label="Course Link" className="cta">
                      Learn More
                    </a>
                  )}
                  {github && (
                    <a href={github} aria-label="GitHub Link">
                      <Icon name="GitHub" />
                    </a>
                  )}
                  {external && !cta && (
                    <a href={external} aria-label="External Link" className="external">
                      <Icon name="External" />
                    </a>
                  )}
                </div>
              </div>
            </div>

            <div className="project-image">
              <a href={external ? external : github ? github : '#'}>
                <GatsbyImage image={image} alt={title} className="img" />
              </a>
            </div>
          </StyledProject>
        );
      })}
  </StyledProjectsGrid>
);

FeaturedGrid.propTypes = {
  projects: PropTypes.array.isRequired,
  overline: PropTypes.string.isRequired,
  showcase: PropTypes.bool,
  revealRefs: PropTypes.object,
};

FeaturedGrid.defaultProps = {
  showcase: false,
};

export default FeaturedGrid;
